#include "analysis/WorldAnalyzer.h"
namespace sanbucraft::analysis { namespace { void add(WorldAnalysis& result, const std::vector<sanbucraft::minecraft::ItemStack>& items) { for (const auto& item : items) { result.items[item.id] += item.count; if (item.id.find("bread") != std::string::npos || item.id.find("food") != std::string::npos || item.id.find("cooked_") != std::string::npos) result.food += item.count; } } }
WorldAnalysis WorldAnalyzer::analyze(const std::vector<sanbucraft::minecraft::Player>& players, const std::vector<sanbucraft::minecraft::Container>& containers) { WorldAnalysis result; result.containers = static_cast<int>(containers.size()); for (const auto& player : players) { add(result, player.inventory); add(result, player.armor); add(result, player.enderChest); } for (const auto& container : containers) add(result, container.items); return result; }
std::vector<sanbucraft::minecraft::Container> WorldAnalyzer::findContainers(const std::vector<sanbucraft::minecraft::Container>& containers, const std::string& itemId) { std::vector<sanbucraft::minecraft::Container> result; for (const auto& container : containers) for (const auto& item : container.items) if (item.id == itemId) { result.push_back(container); break; } return result; }
}
